package git

import (
	"bytes"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/buchin/cuan/internal/agent"
)

// regenerableIgnoredBuildDirs lists gitignored build/dependency directories that
// can always be regenerated by npm/go/vite and must not block stale workspace pruning.
var regenerableIgnoredBuildDirs = map[string]string{
	"!! node_modules/":     "node_modules",
	"!! web/node_modules/": "web/node_modules",
	"!! dist/":             "dist",
	"!! web/dist/":         "web/dist",
	"!! build/":            "build",
	"!! web/build/":        "web/build",
	"!! .next/":            ".next",
	"!! web/.next/":        "web/.next",
	"!! coverage/":         "coverage",
	"!! bin/":              "bin",
}

// A clean published checkout may contain Cuan's exact regenerable MCP defaults
// or regenerable ignored build/dependency directories.
// Never ignore unknown directories, symlinks, or edited files.
func reconstructibleWorkspaceStatus(root string, status []byte) bool {
	if len(bytes.TrimSpace(status)) == 0 {
		return true
	}
	for _, entry := range strings.Split(strings.TrimSuffix(string(status), "\n"), "\n") {
		if relDir, ok := regenerableIgnoredBuildDirs[entry]; ok {
			info, err := os.Lstat(filepath.Join(root, filepath.FromSlash(relDir)))
			if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
				return false
			}
			continue
		}
		var relative, expected string
		switch entry {
		case "!! .agents/":
			relative, expected = ".agents", ".agents/mcp_config.json"
		case "!! .gemini/":
			relative, expected = ".gemini", ".gemini/config/mcp_config.json"
		default:
			return false
		}
		found := false
		err := filepath.WalkDir(filepath.Join(root, relative), func(path string, entry fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			rel, err := filepath.Rel(root, path)
			if err != nil {
				return err
			}
			if entry.IsDir() {
				if rel != relative && !(relative == ".gemini" && rel == filepath.Join(".gemini", "config")) {
					return fs.ErrInvalid
				}
				return nil
			}
			if filepath.ToSlash(rel) != expected || entry.Type()&os.ModeSymlink != 0 {
				return fs.ErrInvalid
			}
			info, err := entry.Info()
			if err != nil || !info.Mode().IsRegular() || info.Size() > 4096 {
				return fs.ErrInvalid
			}
			data, err := os.ReadFile(path)
			if err != nil || !bytes.Equal(data, agent.GeneratedWorkspaceMCPConfig()) {
				return fs.ErrInvalid
			}
			found = true
			return nil
		})
		if err != nil || !found {
			return false
		}
	}
	return true
}
